// Construye la petición para el agente a partir de lo que manda el front end.
const b = $input.first().json.body ?? {};
const accion = b.accion === 'chat' ? 'chat' : 'registrar';
const session_id = /^[\w-]{8,64}$/.test(String(b.session_id ?? '')) ? b.session_id : 'sesion-' + $execution.id;
let chatInput;
if (accion === 'registrar') {
  const texto = String(b.texto_factura ?? '').slice(0, 12000);
  chatInput = 'TAREA: REGISTRAR. Extrae los datos de esta factura, valídala con validar_factura y calcula el vencimiento con calcular_vencimiento.\n<<<FACTURA\n' + texto + '\nFACTURA>>>';
} else {
  const contexto = JSON.stringify(b.contexto ?? []).slice(0, 15000);
  chatInput = 'TAREA: CONSULTA. Pregunta del usuario: ' + String(b.mensaje ?? '').slice(0, 1000) + '\nFacturas actuales (datos reales del sistema, en JSON): ' + contexto;
}
return [{ json: { accion, session_id, chatInput } }];

// Herramienta del agente: valida una factura con una clase POO (enfoque B de la investigación).
class Factura {
  constructor(d) {
    this.subtotal = Number(d.subtotal);
    this.impuestos = Number(d.impuestos ?? 0);
    this.total = Number(d.total);
    this.tasas = Array.isArray(d.tasas) ? d.tasas.map(Number) : [];
    this.fecha = String(d.fecha_emision ?? '');
    this.cedula = String(d.identificacion ?? '').replace(/\D/g, '');
    this.moneda = d.moneda === 'USD' ? 'USD' : 'CRC';
  }
  validar() {
    const errores = [];
    const advertencias = [];
    const tol = this.moneda === 'USD' ? 0.05 : 1;
    if (!(this.total > 0)) errores.push('El total debe ser mayor que cero.');
    const suma = Math.round((this.subtotal + this.impuestos) * 100) / 100;
    if (Math.abs(suma - this.total) > tol) errores.push(`La suma no cuadra: ${this.subtotal} + ${this.impuestos} = ${suma}, pero el total es ${this.total}.`);
    for (const t of this.tasas) if (![0, 1, 2, 4, 13].includes(t)) advertencias.push(`Tarifa de IVA inusual: ${t} %.`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(this.fecha)) errores.push('La fecha debe venir en formato AAAA-MM-DD.');
    if (this.cedula && ![9, 10, 11, 12].includes(this.cedula.length)) errores.push('La cédula no tiene un formato válido.');
    return { valida: errores.length === 0, errores, advertencias };
  }
}
let datos;
try { datos = typeof query === 'string' ? JSON.parse(query) : query; } catch (e) { return JSON.stringify({ valida: false, errores: ['La entrada debe ser un JSON con los datos de la factura.'] }); }
return JSON.stringify(new Factura(datos).validar());

// Herramienta del agente: calcula el vencimiento. Entrada: "AAAA-MM-DD|dias"
const [fecha, dias] = String(query).split('|');
const [a, m, d] = fecha.trim().split('-').map(Number);
const v = new Date(Date.UTC(a, m - 1, d + Number(dias || 30)));
return v.toISOString().slice(0, 10);

// Interfaz común { ok, data, error }: interpreta la salida del agente.
const r = $input.first().json;
const p = $('Preparar petición').first().json;
const pasos = (r.intermediateSteps ?? []).map((s) => ({ herramienta: s.action?.tool ?? '¿?', ok: true, error: null }));
if (r.error) {
  const m = String(r.error.message ?? r.error);
  return [{ json: { ok: false, data: null, error: /429|rate/i.test(m) ? 'Groq alcanzó su límite de uso. Esperá un minuto.' : 'El agente falló: ' + m } }];
}
const salida = typeof r.output === 'string' ? r.output : JSON.stringify(r.output ?? '');
let json = null;
const ini = salida.indexOf('{');
const fin = salida.lastIndexOf('}');
if (ini >= 0 && fin > ini) { try { json = JSON.parse(salida.slice(ini, fin + 1)); } catch (e) { json = null; } }
if (p.accion === 'registrar') {
  if (!json || !json.datos) return [{ json: { ok: false, data: { salida }, error: 'El agente no devolvió los datos en el formato esperado. Intentá de nuevo.' } }];
  return [{ json: { ok: true, data: { ...json, pasos }, error: null } }];
}
return [{ json: { ok: true, data: { mensaje: json?.mensaje ?? salida, pasos }, error: null } }];
